// ============================================================
// h_matrix_rom.v
// Filename must match exactly: h_matrix_rom.v
// Module name: h_matrix_rom  (matches u_rom instantiation)
// Pure case-statement ROM — no initial block, no reg arrays.
// Vivado infers as distributed LUT ROM. Design source only.
// ============================================================
module h_matrix_rom (
    input  wire       clk,
    input  wire [5:0] row_addr,
    output reg [99:0] row_data
);

    always @(posedge clk) begin
        case (row_addr)
            6'd0 : row_data <= 100'b1000000000000000010000000000000000100000000000000001000000000000000010000000000000000100000000000000;
            6'd1 : row_data <= 100'b0100000000000000001000000000000000010000000000000000100000000000000001000000000000000010000000000000;
            6'd2 : row_data <= 100'b0010000000000000000100000000000000001000000000000000010000000000000000100000000000000001000000000000;
            6'd3 : row_data <= 100'b0001000000000000000010000000000000000100000000000000001000000000000000010000000000000000100000000000;
