            6'd32: row_data <= 100'b0000000000000001000000000000000001100000000000000000100000000000000000100000000000000000100000000000;
            6'd33: row_data <= 100'b0000000000000000110000000000000000010000000000000000010000000000000000010000000000000000010000000000;
            6'd34: row_data <= 100'b1000000000000000000100000000000000000010000000000000000001000000000000000000100000000000000000010000;
            6'd35: row_data <= 100'b0100000000000000000010000000000000000001000000000000000000100000000000000000010000000000000000001000;
            6'd36: row_data <= 100'b0010000000000000000001000000000000000000100000000000000000010000000000000000001000000000000000000100;
            6'd37: row_data <= 100'b0001000000000000000000100000000000000000010000000000000000001000000000000000000100000000000000000010;
            6'd38: row_data <= 100'b0000100000000000000000010000000000000000001000000000000000000100000000000000000010000000000000000001;
